/**
 * Success payload returned by write command handlers via Result.ok<WriteResult>.
 * groupId is the UUID stamped by CommandBus onto every edit_actions row written
 * in this API call — the caller can use it for undo/redo/stage/unstage operations
 * (REQ-ATO-01 to REQ-ATO-05 of foundation.md §2).
 */
export type WriteResult = {
  /** UUID generated by CommandBus for this command execution.
   *  All edit_actions rows produced within one execute() call share this value. */
  groupId: string;
};
